-- Dominio transaccional de campañas, misiones, billetera y redenciones NOCTA.
create table public.loyalty_campaigns(id uuid primary key default gen_random_uuid(),name text not null,budget_points bigint not null check(budget_points>0),status text not null default 'draft' check(status in('draft','scheduled','published','paused','finished','cancelled')),starts_at timestamptz,ends_at timestamptz,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.loyalty_missions(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.loyalty_campaigns(id) on delete cascade,slug text not null unique,name text not null,description text not null default '',reward_points integer not null check(reward_points>0),starts_at timestamptz not null,ends_at timestamptz not null,total_quota integer not null check(total_quota>0),per_user_quota integer not null check(per_user_quota>0),frequency text not null check(frequency in('once','daily','weekly','monthly','campaign')),requires_audit boolean not null default false,evidence_schema jsonb not null default '{}'::jsonb,status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.loyalty_executions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),mission_id uuid not null references public.loyalty_missions(id),campaign_id uuid not null references public.loyalty_campaigns(id),status text not null check(status in('accepted','in_progress','submitted','in_review','needs_fix','approved','rejected','expired')),evidence jsonb not null default '{}'::jsonb,submitted_at timestamptz,auditor_id uuid references public.profiles(id),review_notes text,points_awarded integer,idempotency_key text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,idempotency_key));
create table public.wallet_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),kind text not null check(kind in('mission_credit','adjustment','reversal','redemption','expiration')),status text not null check(status in('pending','confirmed','reversed')),points integer not null check(points<>0),concept text not null,mission_id uuid references public.loyalty_missions(id),execution_id uuid references public.loyalty_executions(id),redemption_id uuid,idempotency_key text not null,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(user_id,idempotency_key));
create unique index wallet_one_credit_per_execution on public.wallet_transactions(execution_id) where kind='mission_credit' and status<>'reversed';create index wallet_user_date on public.wallet_transactions(user_id,created_at desc);
create table public.loyalty_rewards(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,description text not null,image_url text,points_required integer not null check(points_required>0),stock integer not null check(stock>=0),active boolean not null default true,venue_id uuid not null references public.venues(id),city text,category text,terms text not null default '',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.loyalty_settings(id boolean primary key default true check(id),token_ttl_minutes integer not null default 1440 check(token_ttl_minutes>0),token_validation_rate_limit integer not null default 10 check(token_validation_rate_limit>0),redemption_max_points integer not null default 100000 check(redemption_max_points>0),adjustment_dual_approval_threshold integer not null default 10000 check(adjustment_dual_approval_threshold>0),audit_retention_days integer not null default 730 check(audit_retention_days>0));insert into public.loyalty_settings(id) values(true);
create table public.loyalty_redemptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),reward_id uuid not null references public.loyalty_rewards(id),points integer not null check(points>0),status text not null default 'requested' check(status in('requested','approved','delivered','rejected','cancelled')),token text not null,token_hash text not null unique,idempotency_key text not null,created_at timestamptz not null default now(),expires_at timestamptz not null,redeemed_at timestamptz,validated_by_user_id uuid references public.profiles(id),unique(user_id,idempotency_key));
create or replace function public.secure_loyalty_token() returns text language plpgsql volatile security definer set search_path='' as $$ declare alphabet constant text:='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';bytes bytea;raw text;candidate text;i integer;attempt integer;begin for attempt in 1..10 loop bytes:=gen_random_bytes(12);raw:='';for i in 0..11 loop raw:=raw||substr(alphabet,1+(get_byte(bytes,i)%32),1);end loop;candidate:=substr(raw,1,4)||'-'||substr(raw,5,4)||'-'||substr(raw,9,4);if not exists(select 1 from public.loyalty_redemptions where token_hash=encode(digest(candidate,'sha256'),'hex')) then return candidate;end if;end loop;raise exception 'TOKEN_GENERATION_FAILED';end;$$;
create or replace function public.prepare_loyalty_token() returns trigger language plpgsql security definer set search_path='' as $$ declare settings public.loyalty_settings;begin select * into settings from public.loyalty_settings where id=true;if new.points>settings.redemption_max_points then raise exception 'REDEMPTION_LIMIT_EXCEEDED';end if;new.token:=public.secure_loyalty_token();new.token_hash:=encode(digest(new.token,'sha256'),'hex');new.expires_at:=now()+make_interval(mins=>settings.token_ttl_minutes);return new;end;$$;
create trigger loyalty_secure_token before insert on public.loyalty_redemptions for each row execute function public.prepare_loyalty_token();
create or replace function public.guard_loyalty_delivery() returns trigger language plpgsql security definer set search_path='' as $$ declare reward_venue uuid;begin if new.status='delivered' and old.status<>'delivered' then if old.status<>'requested' or old.expires_at<=now() then raise exception 'TOKEN_NOT_DELIVERABLE';end if;if not exists(select 1 from public.profiles where id=old.user_id and status='active') then raise exception 'PARTICIPANT_INACTIVE';end if;if not exists(select 1 from public.profiles where id=auth.uid() and status='active') then raise exception 'ACTOR_INACTIVE';end if;select venue_id into reward_venue from public.loyalty_rewards where id=old.reward_id;if not(public.is_platform_owner() or public.can_manage_venue(reward_venue)) then raise exception 'WRONG_MERCHANT';end if;new.redeemed_at:=now();new.validated_by_user_id:=auth.uid();end if;return new;end;$$;
create trigger loyalty_delivery_guard before update of status on public.loyalty_redemptions for each row execute function public.guard_loyalty_delivery();
alter table public.wallet_transactions add constraint wallet_redemption_fk foreign key(redemption_id) references public.loyalty_redemptions(id);create index loyalty_redemptions_user on public.loyalty_redemptions(user_id,status,created_at desc);create index loyalty_redemptions_expiry on public.loyalty_redemptions(expires_at) where status='requested';

alter table public.loyalty_campaigns enable row level security;alter table public.loyalty_missions enable row level security;alter table public.loyalty_executions enable row level security;alter table public.wallet_transactions enable row level security;alter table public.loyalty_rewards enable row level security;alter table public.loyalty_redemptions enable row level security;
create policy "published campaigns read" on public.loyalty_campaigns for select using(status='published' or public.is_platform_owner());create policy "active missions read" on public.loyalty_missions for select using(status='active' or public.is_platform_owner());create policy "execution self read" on public.loyalty_executions for select using(user_id=auth.uid() or public.current_user_has_any_role(array['platform_owner','analyst']));create policy "wallet self read" on public.wallet_transactions for select using(user_id=auth.uid() or public.is_platform_owner());create policy "active rewards read" on public.loyalty_rewards for select using(active or public.is_platform_owner() or public.can_manage_venue(venue_id));create policy "redemption self or merchant read" on public.loyalty_redemptions for select using(user_id=auth.uid() or public.is_platform_owner() or exists(select 1 from public.loyalty_rewards r where r.id=reward_id and public.can_manage_venue(r.venue_id)));
grant select on public.loyalty_campaigns,public.loyalty_missions,public.loyalty_executions,public.wallet_transactions,public.loyalty_rewards,public.loyalty_redemptions to authenticated;
create policy "platform campaigns manage" on public.loyalty_campaigns for all using(public.is_platform_owner()) with check(public.is_platform_owner());
create policy "platform missions manage" on public.loyalty_missions for all using(public.is_platform_owner()) with check(public.is_platform_owner());
create policy "authorized rewards manage" on public.loyalty_rewards for all using(public.is_platform_owner() or public.can_manage_venue(venue_id)) with check(public.is_platform_owner() or public.can_manage_venue(venue_id));
grant insert,update on public.loyalty_campaigns,public.loyalty_missions,public.loyalty_rewards to authenticated;

create or replace function public.wallet_balance(target_user uuid default auth.uid()) returns table(available bigint,pending bigint,total bigint,redeemed bigint) language sql stable security definer set search_path='' as $$ select coalesce(sum(case when status='confirmed' then points else 0 end),0)::bigint,coalesce(sum(case when status='pending' and kind<>'redemption' then points else 0 end),0)::bigint,coalesce(sum(case when status='confirmed' and points>0 then points else 0 end),0)::bigint,coalesce(sum(case when status<>'reversed' and kind='redemption' then abs(points) else 0 end),0)::bigint from public.wallet_transactions where user_id=target_user and status<>'reversed' and (target_user=auth.uid() or public.is_platform_owner());$$;

create or replace function public.credit_approved_execution(execution_key uuid,actor uuid) returns integer language plpgsql security definer set search_path='' as $$ declare execution public.loyalty_executions;mission public.loyalty_missions;campaign public.loyalty_campaigns;issued bigint;existing public.wallet_transactions;begin select * into execution from public.loyalty_executions where id=execution_key for update;if not found then raise exception 'EXECUTION_NOT_FOUND';end if;select * into mission from public.loyalty_missions where id=execution.mission_id;select * into campaign from public.loyalty_campaigns where id=execution.campaign_id for update;select * into existing from public.wallet_transactions where execution_id=execution.id and kind='mission_credit' and status<>'reversed';if found and existing.status='confirmed' then return coalesce(execution.points_awarded,mission.reward_points);end if;select coalesce(sum(points),0) into issued from public.wallet_transactions wt join public.loyalty_missions m on m.id=wt.mission_id where m.campaign_id=campaign.id and wt.kind='mission_credit' and wt.status='confirmed';if issued+mission.reward_points>campaign.budget_points then raise exception 'CAMPAIGN_BUDGET_EXCEEDED';end if;if existing.id is null then insert into public.wallet_transactions(user_id,kind,status,points,concept,mission_id,execution_id,idempotency_key,created_by) values(execution.user_id,'mission_credit','confirmed',mission.reward_points,'Misión aprobada · '||mission.name,mission.id,execution.id,'credit:'||execution.id,actor);else update public.wallet_transactions set status='confirmed',concept='Misión aprobada · '||mission.name,created_by=actor where id=existing.id;end if;update public.loyalty_executions set status='approved',points_awarded=mission.reward_points,auditor_id=actor,updated_at=now() where id=execution.id;insert into public.audit_logs(actor_id,action,entity_type,entity_id,metadata) values(actor,'execution_approved','loyalty_execution',execution.id,jsonb_build_object('points',mission.reward_points));return mission.reward_points;end;$$;

create or replace function public.submit_mission_execution(mission_slug text,evidence jsonb,idempotency_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare mission public.loyalty_missions;execution_id uuid;period_start timestamptz;user_count integer;total_count integer;missing_key boolean;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;select m.* into mission from public.loyalty_missions m join public.loyalty_campaigns c on c.id=m.campaign_id where m.slug=mission_slug and m.status='active' and c.status='published' and now() between m.starts_at and m.ends_at;if not found then raise exception 'MISSION_UNAVAILABLE';end if;select exists(select 1 from jsonb_array_elements_text(coalesce(mission.evidence_schema->'required','[]'::jsonb)) key where not coalesce(evidence,'{}'::jsonb)?key) into missing_key;if missing_key then raise exception 'EVIDENCE_REQUIRED';end if;select count(*) into total_count from public.loyalty_executions where mission_id=mission.id and status in('submitted','in_review','approved');if total_count>=mission.total_quota then raise exception 'MISSION_QUOTA_REACHED';end if;period_start:=case mission.frequency when 'daily' then date_trunc('day',now()) when 'weekly' then date_trunc('week',now()) when 'monthly' then date_trunc('month',now()) else mission.starts_at end;select count(*) into user_count from public.loyalty_executions where mission_id=mission.id and user_id=auth.uid() and status in('submitted','in_review','approved') and created_at>=period_start;if user_count>=mission.per_user_quota then raise exception 'USER_QUOTA_REACHED';end if;insert into public.loyalty_executions(user_id,mission_id,campaign_id,status,evidence,submitted_at,idempotency_key) values(auth.uid(),mission.id,mission.campaign_id,case when mission.requires_audit then 'in_review' else 'submitted' end,coalesce(evidence,'{}'::jsonb),now(),idempotency_key) on conflict(user_id,idempotency_key) do update set idempotency_key=excluded.idempotency_key returning id into execution_id;if mission.requires_audit then insert into public.wallet_transactions(user_id,kind,status,points,concept,mission_id,execution_id,idempotency_key,created_by) values(auth.uid(),'mission_credit','pending',mission.reward_points,'Misión en revisión · '||mission.name,mission.id,execution_id,'pending:'||execution_id,auth.uid()) on conflict do nothing;else perform public.credit_approved_execution(execution_id,auth.uid());end if;return execution_id;end;$$;

create or replace function public.review_mission_execution(execution_key uuid,decision text,notes text default '') returns void language plpgsql security definer set search_path='' as $$ declare execution public.loyalty_executions;begin if not public.current_user_has_any_role(array['platform_owner','analyst']) then raise exception 'FORBIDDEN';end if;if decision not in('needs_fix','approved','rejected') then raise exception 'INVALID_DECISION';end if;select * into execution from public.loyalty_executions where id=execution_key and status='in_review' for update;if not found then raise exception 'EXECUTION_NOT_REVIEWABLE';end if;if decision='approved' then perform public.credit_approved_execution(execution.id,auth.uid());else update public.loyalty_executions set status=decision,review_notes=notes,auditor_id=auth.uid(),updated_at=now() where id=execution.id;update public.wallet_transactions set status='reversed' where execution_id=execution.id and kind='mission_credit' and status='pending';end if;end;$$;

create or replace function public.reconcile_expired_redemptions(target_user uuid default null) returns integer language plpgsql security definer set search_path='' as $$ declare item record;count_reversed integer:=0;begin for item in select r.id,r.reward_id from public.loyalty_redemptions r where r.status='requested' and r.expires_at<=now() and (target_user is null or r.user_id=target_user) for update loop update public.loyalty_redemptions set status='cancelled' where id=item.id;update public.wallet_transactions set status='reversed' where redemption_id=item.id and kind='redemption' and status<>'reversed';update public.loyalty_rewards set stock=stock+1,updated_at=now() where id=item.reward_id;insert into public.audit_logs(actor_id,action,entity_type,entity_id) values(auth.uid(),'redemption_cancelled','loyalty_redemption',item.id);count_reversed:=count_reversed+1;end loop;return count_reversed;end;$$;

create or replace function public.redeem_loyalty_reward(reward_slug text,request_key text) returns table(id uuid,token text,expires_at timestamptz) language plpgsql security definer set search_path='' as $$ declare reward public.loyalty_rewards;balance record;new_id uuid;raw_token text;expiration timestamptz;attempt integer:=0;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;perform public.reconcile_expired_redemptions(auth.uid());perform pg_advisory_xact_lock(hashtext(auth.uid()::text));select * into reward from public.loyalty_rewards where slug=reward_slug and active for update;if not found then raise exception 'REWARD_NOT_FOUND';end if;if reward.stock<=0 then raise exception 'OUT_OF_STOCK';end if;select * into balance from public.wallet_balance(auth.uid());if balance.available<reward.points_required then raise exception 'INSUFFICIENT_POINTS';end if;loop attempt:=attempt+1;select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789',1+floor(random()*32)::integer,1),'') into raw_token from generate_series(1,12);raw_token:=substr(raw_token,1,4)||'-'||substr(raw_token,5,4)||'-'||substr(raw_token,9,4);exit when not exists(select 1 from public.loyalty_redemptions where token_hash=encode(digest(raw_token,'sha256'),'hex'));if attempt>=10 then raise exception 'TOKEN_GENERATION_FAILED';end if;end loop;expiration:=now()+interval '24 hours';insert into public.loyalty_redemptions(user_id,reward_id,points,status,token,token_hash,idempotency_key,expires_at) values(auth.uid(),reward.id,reward.points_required,'requested',raw_token,encode(digest(raw_token,'sha256'),'hex'),request_key,expiration) on conflict(user_id,idempotency_key) do update set idempotency_key=excluded.idempotency_key returning public.loyalty_redemptions.id,public.loyalty_redemptions.token,public.loyalty_redemptions.expires_at into new_id,raw_token,expiration;if not exists(select 1 from public.wallet_transactions where redemption_id=new_id) then update public.loyalty_rewards set stock=stock-1,updated_at=now() where id=reward.id and stock>0;if not found then raise exception 'OUT_OF_STOCK';end if;insert into public.wallet_transactions(user_id,kind,status,points,concept,redemption_id,idempotency_key,created_by) values(auth.uid(),'redemption','confirmed',-reward.points_required,'Reserva de beneficio · '||reward.name,new_id,'redemption:'||new_id,auth.uid());insert into public.audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'redemption_request','loyalty_redemption',new_id,jsonb_build_object('reward_id',reward.id,'points',reward.points_required));end if;id:=new_id;token:=raw_token;expires_at:=expiration;return next;end;$$;

create or replace function public.check_loyalty_token(raw_token text) returns table(valid boolean,reason text,redemption_id uuid,reward_name text,participant_name text,venue_name text,expires_at timestamptz) language plpgsql security definer set search_path='' as $$ declare item public.loyalty_redemptions;reward public.loyalty_rewards;recent_failures integer;begin select count(*) into recent_failures from public.audit_logs where actor_id=auth.uid() and action='token_validation_failed' and created_at>now()-interval '1 minute';if recent_failures>=10 then raise exception 'RATE_LIMITED';end if;select * into item from public.loyalty_redemptions where token_hash=encode(digest(upper(trim(raw_token)),'sha256'),'hex');if not found then insert into public.audit_logs(actor_id,action,entity_type,metadata) values(auth.uid(),'token_validation_failed','loyalty_redemption',jsonb_build_object('reason','not_found'));valid:=false;reason:='invalid';return next;return;end if;select * into reward from public.loyalty_rewards where id=item.reward_id;if not (public.is_platform_owner() or public.can_manage_venue(reward.venue_id)) then raise exception 'WRONG_MERCHANT';end if;if item.status<>'requested' then valid:=false;reason:=item.status;return next;return;end if;if item.expires_at<=now() then perform public.reconcile_expired_redemptions(item.user_id);valid:=false;reason:='expired';return next;return;end if;valid:=true;reason:='ok';redemption_id:=item.id;reward_name:=reward.name;expires_at:=item.expires_at;select nullif(full_name,'') into participant_name from public.profiles where id=item.user_id;select name into venue_name from public.venues where id=reward.venue_id;return next;end;$$;

create or replace function public.consume_loyalty_token(raw_token text) returns table(result text,reward_name text,participant_name text) language plpgsql security definer set search_path='' as $$ declare checked record;updated_id uuid;begin select * into checked from public.check_loyalty_token(raw_token);if not checked.valid then result:=checked.reason;return next;return;end if;update public.loyalty_redemptions set status='delivered',redeemed_at=now(),validated_by_user_id=auth.uid() where id=checked.redemption_id and status='requested' and expires_at>now() returning id into updated_id;if updated_id is null then result:='used';return next;return;end if;result:='delivered';reward_name:=checked.reward_name;participant_name:=checked.participant_name;insert into public.audit_logs(actor_id,action,entity_type,entity_id) values(auth.uid(),'redemption_delivered','loyalty_redemption',updated_id);return next;end;$$;

create or replace function public.adjust_wallet(target_user uuid,adjustment_points integer,concept text,request_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare tx_id uuid;balance record;begin if not public.is_platform_owner() then raise exception 'FORBIDDEN';end if;if adjustment_points=0 or nullif(btrim(concept),'') is null then raise exception 'INVALID_ADJUSTMENT';end if;select * into balance from public.wallet_balance(target_user);if adjustment_points<0 and balance.available+adjustment_points<0 then raise exception 'INSUFFICIENT_POINTS';end if;insert into public.wallet_transactions(user_id,kind,status,points,concept,idempotency_key,created_by) values(target_user,'adjustment','confirmed',adjustment_points,btrim(concept),request_key,auth.uid()) returning id into tx_id;insert into public.audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'wallet_adjust','wallet_transaction',tx_id,jsonb_build_object('points',adjustment_points,'target_user',target_user));return tx_id;end;$$;

revoke all on function public.wallet_balance(uuid),public.credit_approved_execution(uuid,uuid),public.submit_mission_execution(text,jsonb,text),public.review_mission_execution(uuid,text,text),public.reconcile_expired_redemptions(uuid),public.redeem_loyalty_reward(text,text),public.check_loyalty_token(text),public.consume_loyalty_token(text),public.adjust_wallet(uuid,integer,text,text) from public,anon;
grant execute on function public.wallet_balance(uuid),public.submit_mission_execution(text,jsonb,text),public.redeem_loyalty_reward(text,text),public.reconcile_expired_redemptions(uuid),public.review_mission_execution(uuid,text,text),public.check_loyalty_token(text),public.consume_loyalty_token(text),public.adjust_wallet(uuid,integer,text,text) to authenticated;
with owner as(select user_id from public.platform_members where role='platform_owner' limit 1) insert into public.loyalty_campaigns(name,budget_points,status,starts_at,ends_at,created_by) select 'Asistencias verificadas',10000000,'published','2026-01-01','2030-12-31',user_id from owner;
insert into public.loyalty_missions(campaign_id,slug,name,description,reward_points,starts_at,ends_at,total_quota,per_user_quota,frequency,requires_audit,evidence_schema) select id,'verified-attendance','Asistencia verificada','Puntos automáticos cuando el equipo valida una entrada, reserva o lista.',100,starts_at,ends_at,100000,1000,'campaign',false,'{"system":true}'::jsonb from public.loyalty_campaigns where name='Asistencias verificadas' limit 1;
create or replace function public.sync_verified_attendance() returns integer language plpgsql security definer set search_path='' as $$ declare mission public.loyalty_missions;source record;execution_id uuid;credited integer:=0;begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;select * into mission from public.loyalty_missions where slug='verified-attendance';if not found then return 0;end if;for source in select 'ticket'::text kind,t.id::text source_id,coalesce(t.used_by,auth.uid()) actor from public.tickets t where t.holder_user_id=auth.uid() and t.status='used' union all select 'reservation',r.id::text,auth.uid() from public.reservations r where r.customer_user_id=auth.uid() and r.status in('checked_in','completed') union all select 'guest_list',g.id::text,coalesce(g.checked_in_by,auth.uid()) from public.guest_list_entries g where g.guest_user_id=auth.uid() and g.status='checked_in' loop execution_id:=null;insert into public.loyalty_executions(user_id,mission_id,campaign_id,status,evidence,submitted_at,idempotency_key) values(auth.uid(),mission.id,mission.campaign_id,'submitted',jsonb_build_object('source_type',source.kind,'source_id',source.source_id),now(),'verified:'||source.kind||':'||source.source_id) on conflict(user_id,idempotency_key) do nothing returning id into execution_id;if execution_id is not null then perform public.credit_approved_execution(execution_id,source.actor);credited:=credited+1;end if;end loop;return credited;end;$$;
revoke all on function public.sync_verified_attendance() from public,anon;grant execute on function public.sync_verified_attendance() to authenticated;
notify pgrst,'reload schema';
